class BusinessDetailScreen extends ConsumerWidget{ const BusinessDetailScreen({required this.businessId,super.key}); final String businessId; @override Widget build(BuildContext context,WidgetRef ref){ final business=ref.watch(businessDetailProvider(businessId)); return Scaffold(body:business.when(data:(item){final q=item.queue; return CustomScrollView(slivers:[SliverAppBar(pinned:true,expandedHeight:220,flexibleSpace:FlexibleSpaceBar(title:Text(item.name,maxLines:1,overflow:TextOverflow.ellipsis),background:item.imageUrl==null?Container(color:Theme.of(context).colorScheme.primaryContainer,child:const Icon(Icons.storefront_outlined,size:72)):Image.network(item.imageUrl!,fit:BoxFit.cover,errorBuilder:(_,_,_)=>const Icon(Icons.storefront_outlined,size:72)))),SliverPadding(padding:const EdgeInsets.all(16),sliver:SliverList.list(children:[Row(children:[const Icon(Icons.star,size:18),const SizedBox(width:4),Text(item.rating?.toStringAsFixed(1)??'-'),const SizedBox(width:12),Expanded(child:Text(item.category.name))]),const SizedBox(height:8),Row(crossAxisAlignment:CrossAxisAlignment.start,children:[const Icon(Icons.place_outlined,size:20),const SizedBox(width:8),Expanded(child:Text(item.address))]),const SizedBox(height:16),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Queue Status',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:12),Text(q.status,style:TextStyle(color:Theme.of(context).colorScheme.primary,fontWeight:FontWeight.w700)),const SizedBox(height:16),Row(children:[Expanded(child:_Stat(label:'Now Serving',value:q.currentNumber??'-')),Expanded(child:_Stat(label:'People Waiting',value:'${q.peopleWaiting}')),Expanded(child:_Stat(label:'Estimated Time',value:'${q.estimatedWaitingTimeMinutes} min'))])]))),const SizedBox(height:16),Text('Services',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:8),if(item.services.isEmpty)const Text('No services listed yet.') else ...item.services.map((s)=>ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.room_service_outlined),title:Text(s.name),subtitle:s.estimatedDurationMinutes==null?null:Text('${s.estimatedDurationMinutes} min average'))),const SizedBox(height:16),FilledButton.icon(onPressed:q.id==null?null:()=>context.go('/businesses/$businessId/confirm-queue'),icon:const Icon(Icons.add),label:const Text('Join Queue')),const SizedBox(height:8),const Text('Confirm before joining so your estimated wait is clear.')]))]);},loading:()=>const LoadingStateView(),error:(_,_)=>ErrorStateView(message:'Unable to load business detail.',onRetry:()=>ref.invalidate(businessDetailProvider(businessId)))));}}
class _Stat extends StatelessWidget{ const _Stat({required this.label,required this.value}); final String label; final String value; @override Widget build(BuildContext context)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(value,style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:4),Text(label,style:Theme.of(context).textTheme.bodySmall)]);}